// Demo database of the guided tours (app/tours): DuckDB in memory, its tables generated by SQL instead of shipped data
import type { ConnectionConfig } from './types.ts'

export const demoVariants = ['default', 'production'] as const
export type DemoVariant = (typeof demoVariants)[number]

/** The demo connection; `production` has the guard rails of a production database. */
export function demoConnection(variant: DemoVariant): Partial<ConnectionConfig> {
  const base = { dialect: 'duckdb', file: ':memory:' } as const
  return variant === 'production'
    ? { ...base, name: 'Colwerk Demo (Production)', color: 'red', confirmWrites: true, requireWhere: true }
    : { ...base, name: 'Colwerk Demo' }
}

/**
 * Creates the demo tables and adds missing rows, so it can run on every tour start: the in-memory database is empty
 * after each restart, and rows deleted in a tour come back.
 */
export const DEMO_SETUP_SQL = `
create table if not exists customers (
    id integer primary key, name varchar not null, city varchar, email varchar, active boolean, created_on date);
create table if not exists products (id integer primary key, name varchar not null, price decimal(10, 2));
create table if not exists orders (
    id integer primary key,
    customer_id integer references customers (id),
    product_id integer references products (id),
    quantity integer,
    ordered_on date);
insert or ignore into customers
select i,
    ['Anna', 'Ben', 'Clara', 'David', 'Emma', 'Felix', 'Greta'][i % 7 + 1] || ' '
        || ['Fischer', 'Weber', 'Wagner', 'Becker', 'Hoffmann'][i % 5 + 1],
    ['Berlin', 'Hamburg', 'Munich', 'Cologne', 'Leipzig'][i % 5 + 1],
    'customer' || i || '@example.com',
    i % 6 <> 0,
    date '2025-01-01' + (i * 7)::int
from range(1, 51) t(i);
insert or ignore into products
values (1, 'Keyboard', 49.90), (2, 'Monitor', 229.00), (3, 'Mouse', 19.90), (4, 'Laptop', 1299.00), (5, 'Headset', 89.00);
insert or ignore into orders
select i, i * 7 % 50 + 1, i % 5 + 1, i * 37 % 9 + 1, date '2026-01-01' + (i * 7 % 300)::int
from range(1, 201) t(i);
`
